// QuickCut service worker: only a speed-up. The site works exactly the same without it (first visit,
// private windows, browsers or settings that block service workers); nothing depends on it.
//
// What it does: keeps one complete, versioned copy of the site's own files (the list and hashes come
// from sw-manifest.js, generated by tools/gen-sw-manifest.py) and answers requests for
// those files from it, so repeat visits don't revalidate ~40 files and the app loads offline.
//
// Updates: a new version downloads ALL its files into its own cache, checks every hash, and only then
// activates (skipWaiting); until then the old version keeps serving. A failed or partial download
// leaves the old version in place and is retried at the next update check. Pages are always served
// from one complete version. Nothing is forced: the page just gets a quiet "reload" notice.
//
// What it never touches: other origins, POST/non-GET, Range requests, anything not in the manifest
// (user files, the licenses pages). blob: and data: URLs never reach a worker.
importScripts("sw-manifest.js");

const CACHE = `qc-${self.QC_VERSION}`;
const FILES = self.QC_FILES; // { "shell.js": "<hash>", ... }
const SCOPE = new URL("./", self.location).pathname; // "/" in production

const pathOf = (url) => {
  const p = url.pathname;
  if (!p.startsWith(SCOPE)) return null;
  const rel = decodeURIComponent(p.slice(SCOPE.length));
  return rel === "" ? "index.html" : rel;
};

async function sha(buf) {
  const d = await crypto.subtle.digest("SHA-256", buf);
  return [...new Uint8Array(d)].map((b) => b.toString(16).padStart(2, "0")).join("").slice(0, 16);
}

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    const have = new Set((await cache.keys()).map((r) => pathOf(new URL(r.url))));
    const todo = Object.keys(FILES).filter((f) => !have.has(f));
    let i = 0;
    // a few at a time, revalidating with the server (never trusting the browser's HTTP cache)
    const worker = async () => {
      while (i < todo.length) {
        const f = todo[i++];
        // index.html is fetched as "/" (the server may redirect /index.html, and a redirected response
        // can't be used for a page load)
        const res = await fetch(new Request(SCOPE + (f === "index.html" ? "" : f), { cache: "no-cache", credentials: "same-origin" }));
        if (!res.ok) throw new Error(`${f}: ${res.status}`);
        const body = await res.arrayBuffer();
        // HTML pages are not hash-checked: security software and proxies may inject into them, and
        // that must not stop the service worker from installing (they only name files, never contain code)
        if (!/\.html?$/.test(f) && (await sha(body)) !== FILES[f]) throw new Error(`${f}: changed during download`);
        // keep the server's headers (the page's CSP lives there), minus the ones that describe the wire encoding
        const headers = new Headers(res.headers);
        headers.delete("content-encoding"); headers.delete("content-length");
        await cache.put(SCOPE + f, new Response(body, { status: 200, headers }));
      }
    };
    try {
      await Promise.all([worker(), worker(), worker(), worker()]);
    } catch (e) {
      await caches.delete(CACHE); // incomplete: drop it, the old version stays active
      throw e;
    }
    await self.skipWaiting(); // the set is complete and verified
  })());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith("qc-") && k !== CACHE) await caches.delete(k);
  })());
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET" || req.headers.has("range")) return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  const rel = pathOf(url);
  if (rel === null) return;
  if (!(rel in FILES)) return; // not ours to cache (other pages, anything else): network
  event.respondWith((async () => {
    const hit = await (await caches.open(CACHE)).match(SCOPE + rel);
    if (hit) return hit;
    return fetch(req); // not cached (yet): behave as if there were no service worker
  })());
});
